#!/usr/bin/env python3
"""Generate the node reference in docs/NODES.md from the live classes (ids, names, categories, descriptions, inputs, outputs), between the markers below. Text above the markers is hand-written and kept. Needs a ComfyUI checkout for the V3 nodes (COMFYUI_PATH). Runs on the CPU and starts no server."""
import collections, importlib.util, json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); DOC = os.path.join(ROOT, "docs", "NODES.md")
BEGIN, END = "<!-- node reference: generated by scripts/build_node_docs.py, do not edit by hand -->", "<!-- end of generated node reference -->"
def load():
    comfy = __import__("psn.paths", fromlist=["x"]).setting("COMFYUI_PATH", default=os.path.expanduser("~/ComfyUI"))
    if os.path.isdir(os.path.join(comfy, "comfy_api")):
        sys.path.append(comfy); from comfy.cli_args import args; args.cpu = True
    spec = importlib.util.spec_from_file_location("psn_pack", os.path.join(ROOT, "__init__.py"), submodule_search_locations=[ROOT]); m = importlib.util.module_from_spec(spec); sys.modules["psn_pack"] = m; spec.loader.exec_module(m); return m
def cell(text): return " ".join(str(text or "").split()).replace("|", "\\|")
def first_sentence(text):
    text = cell(text); i = text.find(". "); return text if i < 0 else text[:i + 1]
def type_name(t): return "choice" if isinstance(t, (list, tuple)) else {"COMFY_MATCHTYPE_V3": "any (output follows input)", "COMFY_AUTOGROW_V3": "grows as you connect", "COMFY_DYNAMICCOMBO_V3": "choice that reveals controls"}.get(str(t), str(t))
def inputs_of(cls):
    t = cls.INPUT_TYPES(); return [(n, sp, sec) for sec in ("required", "optional") for n, sp in (t.get(sec) or {}).items()]
def flagship_block(cls, display):
    s = cls.GET_SCHEMA(); out = [f"### {display} (`{s.node_id}`)", "", cell(s.description), "", "| Input | Type | What it does |", "|---|---|---|"]
    for name, sp, sec in inputs_of(cls):
        opts = sp[1] if len(sp) > 1 else {}; out.append(f"| `{name}`{' (optional)' if sec == 'optional' else ''} | {type_name(sp[0])} | {cell(opts.get('tooltip'))} |")
        for o in opts.get("options") or []:
            if isinstance(o, dict):
                ctrl = [f"`{n}`" for sec2 in ("required", "optional") for n in (o["inputs"].get(sec2) or {})]; out.append(f"| | `{o['key']}` | {'reveals ' + ', '.join(ctrl) if ctrl else 'no controls'} |")
    out += ["", "Outputs: " + ", ".join(f"`{o.display_name}` ({type_name(o.io_type)})" for o in s.outputs) + ".", ""]; return out
def main():
    m = load(); nodes, disp = m.NODE_CLASS_MAPPINGS, m.NODE_DISPLAY_NAME_MAPPINGS; areas = collections.defaultdict(list); v3 = []
    for k, c in sorted(nodes.items()): (v3 if hasattr(c, "GET_SCHEMA") else areas[c.CATEGORY]).append(k)
    hidden = sum(1 for c in nodes.values() if getattr(c, "DEPRECATED", False) is True)
    out = [BEGIN, "", "## Node reference", "", f"{len(nodes)} nodes: {len(v3)} in the V3 flagship pack and {len(nodes) - len(v3)} more under {len(areas)} areas. {hidden} weak duplicates are hidden from the Add Node menu and keep working in old graphs. Written from the live classes by `scripts/build_node_docs.py`.", "", "## Flagship pack (V3)", "", "Written for `comfy_api.latest`, under `Parametric/Flagship`. A lazy switch is not included because core ships `ComfySwitchNode`.", ""]
    for k in v3: out += flagship_block(nodes[k], disp.get(k, k))
    for area in sorted(areas):
        out += [f"## {area.split('/')[-1]}", "", "| Node | What it does | Inputs | Outputs |", "|---|---|---|---|"]
        for k in areas[area]:
            c = nodes[k]; ins = ", ".join(f"`{n}`" for n, _, _ in inputs_of(c)) or "none"; ret = ", ".join(str(r) if not isinstance(r, (list, tuple)) else "choice" for r in c.RETURN_TYPES) or "none"
            flag = " (hidden)" if getattr(c, "DEPRECATED", False) is True else ""
            out.append(f"| {cell(disp.get(k, k))}{flag}<br>`{k}` | {cell(c.DESCRIPTION if flag else first_sentence(c.DESCRIPTION))} | {ins} | {ret} |")
        out.append("")
    out.append(END); body = "\n".join(out) + "\n"; text = open(DOC, encoding="utf-8").read()
    if BEGIN in text and END in text: text = text[:text.index(BEGIN)] + body + text[text.index(END) + len(END) + 1:]
    else: text = text.rstrip() + "\n\n" + body
    open(DOC, "w", encoding="utf-8").write(text); print(f"{DOC}: {len(nodes)} nodes, {len(v3)} V3, {len(areas)} areas, {hidden} hidden, {len(text) // 1024} KB")
if __name__ == "__main__": main()
